// Command gen generates the SDK's types and services from spec/openapi.json,
// the OpenAPI document cultus derives from its own code (cultus: make openapi).
//
//	go generate ./...                       # from spec/openapi.json
//	go run ./internal/gen -spec <path>      # refresh the spec, then generate
//	go run ./internal/gen -check            # fail if generated files are stale
//
// Only operations with x-linkvite-visibility "public" and an x-linkvite-sdk
// name ("namespace.method") become methods. Field types mirror cultus: nullable
// fields are pointers, optional ones are omitempty values.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type schema struct {
	Ref                  string             `json:"$ref"`
	Type                 any                `json:"type"`
	Format               string             `json:"format"`
	Description          string             `json:"description"`
	Properties           map[string]*schema `json:"properties"`
	Required             []string           `json:"required"`
	Items                *schema            `json:"items"`
	AdditionalProperties any                `json:"additionalProperties"`
	AnyOf                []*schema          `json:"anyOf"`
	Enum                 []any              `json:"enum"`
	Const                any                `json:"const"`
	Default              any                `json:"default"`
	ContentEncoding      string             `json:"contentEncoding"`
}

type parameter struct {
	Name     string  `json:"name"`
	In       string  `json:"in"`
	Required bool    `json:"required"`
	Schema   *schema `json:"schema"`
}

type mediaType struct {
	Schema *schema `json:"schema"`
}

type operation struct {
	OperationID string                                  `json:"operationId"`
	Summary     string                                  `json:"summary"`
	Description string                                  `json:"description"`
	Parameters  []parameter                             `json:"parameters"`
	RequestBody *struct{ Content map[string]mediaType } `json:"requestBody"`
	Responses   map[string]struct {
		Ref     string               `json:"$ref"`
		Content map[string]mediaType `json:"content"`
	} `json:"responses"`
	Visibility string   `json:"x-linkvite-visibility"`
	SDK        string   `json:"x-linkvite-sdk"`
	Scopes     []string `json:"x-linkvite-scopes"`
	RateLimit  string   `json:"x-linkvite-rate-limit"`
}

type document struct {
	Info struct {
		Version string `json:"version"`
	} `json:"info"`
	Paths      map[string]map[string]*operation `json:"paths"`
	Components struct {
		Schemas map[string]*schema `json:"schemas"`
	} `json:"components"`
}

func main() {
	specFlag := flag.String("spec", "", "copy this spec into spec/openapi.json first")
	check := flag.Bool("check", false, "fail if generated files are stale")
	dir := flag.String("dir", ".", "SDK root")
	flag.Parse()

	specPath := filepath.Join(*dir, "spec", "openapi.json")
	if *specFlag != "" {
		b, err := os.ReadFile(*specFlag)
		must(err)
		must(os.WriteFile(specPath, b, 0o644))
	}
	raw, err := os.ReadFile(specPath)
	must(err)
	var doc document
	must(json.Unmarshal(raw, &doc))

	g := &gen{doc: &doc, types: map[string]bool{}, extra: map[string]string{}}
	files := map[string][]byte{
		"types_gen.go":    g.types_(),
		"services_gen.go": g.services(),
	}
	stale := false
	for name, src := range files {
		out, err := format.Source(src)
		if err != nil {
			os.WriteFile("/tmp/"+name, src, 0o644)
			fmt.Fprintf(os.Stderr, "gofmt %s: %v (raw at /tmp/%s)\n", name, err, name)
			os.Exit(1)
		}
		path := filepath.Join(*dir, name)
		if *check {
			cur, _ := os.ReadFile(path)
			if !bytes.Equal(cur, out) {
				fmt.Fprintf(os.Stderr, "stale: %s (run go generate ./...)\n", name)
				stale = true
			}
			continue
		}
		must(os.WriteFile(path, out, 0o644))
	}
	if stale {
		os.Exit(1)
	}
	if !*check {
		fmt.Fprintf(os.Stderr, "generated %d methods in %d services from API %s\n", g.methods, g.nsCount, doc.Info.Version)
	}
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

type gen struct {
	doc     *document
	types   map[string]bool   // component names emitted
	extra   map[string]string // inline type name -> source
	methods int
	nsCount int
}

const header = "// Code generated by internal/gen from spec/openapi.json. DO NOT EDIT.\n\n"

/* ------------------------------------------------------------------ naming -- */

var initialisms = map[string]string{
	"id": "ID", "url": "URL", "uri": "URI", "api": "API", "rss": "RSS", "ip": "IP", "otp": "OTP",
	"qr": "QR", "html": "HTML", "json": "JSON", "csv": "CSV", "txt": "TXT", "pdf": "PDF", "mcp": "MCP",
	"oauth": "OAuth", "ids": "IDs", "urls": "URLs", "sso": "SSO", "ui": "UI", "http": "HTTP", "ttl": "TTL",
}

// goName: snake_case / camelCase / kebab -> exported Go name with initialisms.
func goName(s string) string {
	s = regexp.MustCompile(`([a-z0-9])([A-Z])`).ReplaceAllString(s, "${1}_${2}")
	parts := strings.FieldsFunc(s, func(r rune) bool { return r == '_' || r == '-' || r == '.' || r == ' ' || r == '/' })
	var b strings.Builder
	for _, p := range parts {
		lp := strings.ToLower(p)
		if ini, ok := initialisms[lp]; ok {
			b.WriteString(ini)
			continue
		}
		b.WriteString(strings.ToUpper(lp[:1]) + lp[1:])
	}
	out := b.String()
	if out == "" {
		return "X"
	}
	if out[0] >= '0' && out[0] <= '9' {
		out = "N" + out
	}
	return out
}

func refName(ref string) string { return goName(strings.TrimPrefix(ref, "#/components/schemas/")) }

/* ------------------------------------------------------------------- types -- */

func typeNames(s *schema) []string {
	switch t := s.Type.(type) {
	case string:
		return []string{t}
	case []any:
		var out []string
		for _, x := range t {
			out = append(out, fmt.Sprint(x))
		}
		return out
	}
	return nil
}

// nullable reports whether s admits null, and returns the non-null part.
func nullable(s *schema) (*schema, bool) {
	if len(s.AnyOf) == 2 {
		for i, a := range s.AnyOf {
			if fmt.Sprint(a.Type) == "null" {
				return s.AnyOf[1-i], true
			}
		}
	}
	ts := typeNames(s)
	if len(ts) == 2 && (ts[0] == "null" || ts[1] == "null") {
		c := *s
		if ts[0] == "null" {
			c.Type = ts[1]
		} else {
			c.Type = ts[0]
		}
		return &c, true
	}
	return s, false
}

// goType for s; hint names an inline object type if one is needed.
func (g *gen) goType(s *schema, hint string) string {
	if s == nil {
		return "any"
	}
	inner, isNull := nullable(s)
	t := g.baseType(inner, hint)
	if isNull && !strings.HasPrefix(t, "[]") && !strings.HasPrefix(t, "map[") && t != "any" && t != "json.RawMessage" {
		return "*" + t
	}
	return t
}

func (g *gen) baseType(s *schema, hint string) string {
	if s.Ref != "" {
		return refName(s.Ref)
	}
	ts := typeNames(s)
	t := ""
	if len(ts) > 0 {
		t = ts[0]
	}
	switch t {
	case "string":
		switch {
		case s.Format == "date-time":
			return "time.Time"
		case s.Format == "binary":
			return "File"
		case s.ContentEncoding == "base64":
			return "[]byte"
		}
		return "string"
	case "integer":
		switch s.Format {
		case "int32":
			return "int32"
		case "int64":
			return "int64"
		}
		return "int"
	case "number":
		return "float64"
	case "boolean":
		return "bool"
	case "array":
		return "[]" + g.goType(s.Items, hint+"Item")
	case "object":
		if len(s.Properties) == 0 {
			if ap, ok := s.AdditionalProperties.(map[string]any); ok && len(ap) > 0 {
				b, _ := json.Marshal(ap)
				var as schema
				json.Unmarshal(b, &as)
				return "map[string]" + g.goType(&as, hint+"Value")
			}
			return "map[string]any"
		}
		name := hint
		if _, done := g.extra[name]; !done {
			g.extra[name] = "" // reserve (recursion)
			g.extra[name] = g.structDecl(name, s, "")
		}
		return name
	}
	return "any"
}

func (g *gen) structDecl(name string, s *schema, doc string) string {
	var b strings.Builder
	if doc == "" {
		doc = s.Description
	}
	if doc != "" {
		writeComment(&b, "", name+": "+doc)
	}
	fmt.Fprintf(&b, "type %s struct {\n", name)
	req := map[string]bool{}
	for _, r := range s.Required {
		req[r] = true
	}
	keys := make([]string, 0, len(s.Properties))
	for k := range s.Properties {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	used := map[string]bool{}
	for _, k := range keys {
		p := s.Properties[k]
		fn := goName(k)
		for used[fn] {
			fn += "_"
		}
		used[fn] = true
		ft := g.goType(p, name+fn)
		tag := k
		if !req[k] {
			tag += ",omitempty"
		}
		if ft == "File" {
			tag = "-"
		}
		if d := fieldDoc(p); d != "" {
			writeComment(&b, "\t", d)
		}
		fmt.Fprintf(&b, "\t%s %s `json:\"%s\"`\n", fn, ft, tag)
	}
	b.WriteString("}\n\n")
	return b.String()
}

func fieldDoc(p *schema) string {
	inner, _ := nullable(p)
	var parts []string
	if inner.Description != "" {
		parts = append(parts, inner.Description)
	}
	if len(inner.Enum) > 0 {
		var vs []string
		for _, e := range inner.Enum {
			vs = append(vs, fmt.Sprintf("%v", e))
		}
		parts = append(parts, "One of: "+strings.Join(vs, ", ")+".")
	}
	return strings.Join(parts, " ")
}

func writeComment(b *strings.Builder, indent, text string) {
	for _, line := range wrap(text, 76) {
		fmt.Fprintf(b, "%s// %s\n", indent, line)
	}
}

func wrap(s string, n int) []string {
	var out []string
	for _, para := range strings.Split(s, "\n") {
		words := strings.Fields(para)
		line := ""
		for _, w := range words {
			if line != "" && len(line)+1+len(w) > n {
				out = append(out, line)
				line = w
				continue
			}
			if line != "" {
				line += " "
			}
			line += w
		}
		out = append(out, line)
	}
	return out
}

func (g *gen) types_() []byte {
	var b strings.Builder
	b.WriteString(header + "package linkvite\n\nimport (\n\t\"encoding/json\"\n\t\"time\"\n)\n\nvar _ = json.RawMessage{}\nvar _ = time.Time{}\n\n")
	names := make([]string, 0, len(g.doc.Components.Schemas))
	for n := range g.doc.Components.Schemas {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		s := g.doc.Components.Schemas[n]
		gn := goName(n)
		if fmt.Sprint(s.Type) == "object" || len(s.Properties) > 0 {
			b.WriteString(g.structDecl(gn, s, ""))
		} else {
			fmt.Fprintf(&b, "type %s = %s\n\n", gn, g.goType(s, gn+"Value"))
		}
	}
	// inline types discovered while emitting components
	g.flushExtra(&b)
	return []byte(b.String())
}

func (g *gen) flushExtra(b *strings.Builder) {
	done := map[string]bool{}
	for {
		var pending []string
		for k := range g.extra {
			if !done[k] {
				pending = append(pending, k)
			}
		}
		if len(pending) == 0 {
			return
		}
		sort.Strings(pending)
		for _, k := range pending {
			b.WriteString(g.extra[k])
			done[k] = true
		}
	}
}

/* ---------------------------------------------------------------- services -- */

type method struct {
	ns, name, path, verb string
	op                   *operation
}

func (g *gen) services() []byte {
	byNS := map[string][]method{}
	for p, item := range g.doc.Paths {
		for verb, op := range item {
			if op.Visibility != "public" || op.SDK == "" {
				continue
			}
			ns, name, _ := strings.Cut(op.SDK, ".")
			byNS[ns] = append(byNS[ns], method{ns, name, p, strings.ToUpper(verb), op})
		}
	}
	nss := make([]string, 0, len(byNS))
	for ns := range byNS {
		nss = append(nss, ns)
	}
	sort.Strings(nss)
	g.nsCount = len(nss)
	g.extra = map[string]string{}

	var body strings.Builder
	// Services struct + constructor
	body.WriteString("// services holds every API namespace; embedded in Client.\ntype services struct {\n")
	for _, ns := range nss {
		fmt.Fprintf(&body, "\t%s *%sService\n", goName(ns), goName(ns))
	}
	body.WriteString("}\n\nfunc newServices(c *Client) services {\n\treturn services{\n")
	for _, ns := range nss {
		fmt.Fprintf(&body, "\t\t%s: &%sService{c},\n", goName(ns), goName(ns))
	}
	body.WriteString("\t}\n}\n\n")

	for _, ns := range nss {
		ms := byNS[ns]
		sort.Slice(ms, func(i, j int) bool { return ms[i].name < ms[j].name })
		svc := goName(ns) + "Service"
		fmt.Fprintf(&body, "// %s groups the %s endpoints.\ntype %s struct{ c *Client }\n\n", svc, ns, svc)
		for _, m := range ms {
			body.WriteString(g.method(svc, m))
			g.methods++
		}
	}

	var b strings.Builder
	b.WriteString(header + "package linkvite\n\nimport (\n\t\"context\"\n\t\"net/url\"\n\t\"time\"\n)\n\nvar _ = url.Values{}\nvar _ = time.Time{}\n\n")
	b.WriteString(body.String())
	g.flushExtra(&b)
	return []byte(b.String())
}

var pathParam = regexp.MustCompile(`\{([^}]+)\}`)

func (g *gen) method(svc string, m method) string {
	op := m.op
	mName := goName(m.name)
	base := strings.TrimSuffix(svc, "Service") + mName
	var sig, pathArgs []string
	sig = append(sig, "ctx context.Context")
	for _, pp := range pathParam.FindAllStringSubmatch(m.path, -1) {
		arg := lowerFirst(goName(pp[1]))
		sig = append(sig, arg+" string")
		pathArgs = append(pathArgs, fmt.Sprintf("%q: %s", pp[1], arg))
	}

	// body
	bodyArg, multipart := "nil", false
	if op.RequestBody != nil {
		if mt, ok := op.RequestBody.Content["application/json"]; ok {
			t := g.goType(mt.Schema, base+"Request")
			sig = append(sig, "body *"+strings.TrimPrefix(t, "*"))
			bodyArg = "body"
		} else if mt, ok := op.RequestBody.Content["multipart/form-data"]; ok {
			name := base + "Request"
			g.extra[name] = g.multipartDecl(name, mt.Schema)
			sig = append(sig, "body *"+name)
			bodyArg, multipart = "body", true
		}
	}

	// query
	var query []parameter
	for _, p := range op.Parameters {
		if p.In == "query" {
			query = append(query, p)
		}
	}
	queryArg := "nil"
	if len(query) > 0 {
		name := base + "Params"
		g.extra[name] = g.paramsDecl(name, query)
		sig = append(sig, "params *"+name)
		queryArg = "params.values()"
	}

	// response
	ret, kind := g.responseType(op, base+"Response")

	var b strings.Builder
	doc := op.Summary
	if doc == "" {
		doc = m.name
	}
	writeComment(&b, "", mName+": "+strings.TrimSuffix(doc, ".")+".")
	if op.Description != "" {
		b.WriteString("//\n")
		writeComment(&b, "", op.Description)
	}
	var meta []string
	if len(op.Scopes) > 0 {
		meta = append(meta, "Scope: "+strings.Join(op.Scopes, ", ")+".")
	}
	if op.RateLimit != "" {
		meta = append(meta, "Rate limit: "+op.RateLimit+".")
	}
	meta = append(meta, m.verb+" "+m.path)
	b.WriteString("//\n")
	writeComment(&b, "", strings.Join(meta, " "))

	pathMap := "nil"
	if len(pathArgs) > 0 {
		pathMap = "map[string]string{" + strings.Join(pathArgs, ", ") + "}"
	}
	req := fmt.Sprintf("request{method: %q, path: %q, pathParams: %s, query: %s, body: %s, multipart: %v}", m.verb, m.path, pathMap, queryArg, bodyArg, multipart)
	if queryArg != "nil" {
		req = strings.Replace(req, "query: params.values()", "query: params.values()", 1)
	}
	switch kind {
	case "none":
		fmt.Fprintf(&b, "func (s *%s) %s(%s) error {\n\treturn s.c.do(ctx, %s, nil)\n}\n\n", svc, mName, strings.Join(sig, ", "), req)
	case "text":
		fmt.Fprintf(&b, "func (s *%s) %s(%s) (string, error) {\n\tvar out string\n\terr := s.c.do(ctx, %s, &out)\n\treturn out, err\n}\n\n", svc, mName, strings.Join(sig, ", "), req)
	default:
		ptr := !strings.HasPrefix(ret, "[]") && !strings.HasPrefix(ret, "map[") && ret != "any" && ret != "string" && ret != "bool" && ret != "int" && ret != "int64" && ret != "float64"
		if ptr {
			fmt.Fprintf(&b, "func (s *%s) %s(%s) (*%s, error) {\n\tout := new(%s)\n\tif err := s.c.do(ctx, %s, out); err != nil {\n\t\treturn nil, err\n\t}\n\treturn out, nil\n}\n\n", svc, mName, strings.Join(sig, ", "), ret, ret, req)
		} else {
			fmt.Fprintf(&b, "func (s *%s) %s(%s) (%s, error) {\n\tvar out %s\n\terr := s.c.do(ctx, %s, &out)\n\treturn out, err\n}\n\n", svc, mName, strings.Join(sig, ", "), ret, ret, req)
		}
	}
	return b.String()
}

// responseType: the Go type of the success payload (the envelope's data).
func (g *gen) responseType(op *operation, hint string) (string, string) {
	for _, code := range []string{"200", "201", "202"} {
		r, ok := op.Responses[code]
		if !ok {
			continue
		}
		if mt, ok := r.Content["application/json"]; ok && mt.Schema != nil {
			s := mt.Schema
			if d, ok := s.Properties["data"]; ok {
				t := g.goType(d, hint)
				return strings.TrimPrefix(t, "*"), "data"
			}
			if _, ok := s.Properties["ok"]; ok {
				return "", "none"
			}
			return strings.TrimPrefix(g.goType(s, hint), "*"), "data"
		}
		for ct := range r.Content {
			if ct != "application/json" {
				return "string", "text"
			}
		}
		return "", "none"
	}
	return "", "none"
}

func (g *gen) paramsDecl(name string, ps []parameter) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s are the query parameters of the matching method. A nil\n// *%s sends none.\ntype %s struct {\n", name, name, name)
	sort.Slice(ps, func(i, j int) bool { return ps[i].Name < ps[j].Name })
	for _, p := range ps {
		t := g.goType(p.Schema, name+goName(p.Name))
		t = strings.TrimPrefix(t, "*")
		d := fieldDoc(p.Schema)
		if p.Schema != nil && p.Schema.Default != nil {
			d = strings.TrimSpace(d + fmt.Sprintf(" Default: %v.", p.Schema.Default))
		}
		if d != "" {
			writeComment(&b, "\t", d)
		}
		fmt.Fprintf(&b, "\t%s *%s\n", goName(p.Name), t)
	}
	b.WriteString("}\n\n")
	fmt.Fprintf(&b, "func (p *%s) values() url.Values {\n\tv := url.Values{}\n\tif p == nil {\n\t\treturn v\n\t}\n", name)
	for _, p := range ps {
		fmt.Fprintf(&b, "\tif p.%s != nil {\n\t\tv.Set(%q, formatParam(*p.%s))\n\t}\n", goName(p.Name), p.Name, goName(p.Name))
	}
	b.WriteString("\treturn v\n}\n\n")
	return b.String()
}

func (g *gen) multipartDecl(name string, s *schema) string {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s is sent as multipart/form-data.\ntype %s struct {\n", name, name)
	keys := make([]string, 0, len(s.Properties))
	for k := range s.Properties {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	req := map[string]bool{}
	for _, r := range s.Required {
		req[r] = true
	}
	for _, k := range keys {
		p := s.Properties[k]
		t := strings.TrimPrefix(g.goType(p, name+goName(k)), "*")
		if t != "File" {
			t = "*" + t
		} else if !req[k] {
			t = "*File"
		}
		if d := fieldDoc(p); d != "" {
			writeComment(&b, "\t", d)
		}
		fmt.Fprintf(&b, "\t%s %s `form:%q`\n", goName(k), t, k)
	}
	b.WriteString("}\n\n")
	return b.String()
}

func lowerFirst(s string) string {
	for k, v := range initialisms {
		if strings.HasPrefix(s, v) && len(s) == len(v) {
			return k
		}
	}
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
